ROOT.scriptdef:
SET NOCOUNT ON;
INSERT INTO [CDN].[KntRejestr] ( [KRj_ObiTyp] , [KRj_ObiFirma] , [KRj_ObiNumer] , [KRj_ObiLp] , [KRj_TypRejestru] , [KRj_Waluta] , [KRj_PrzypiszDoPlatnosci] , [KRj_NrRachunku] , [KRj_KarNumer] , [KRj_Uwagi] , [KRj_CzasArchiwizacji] ) SELECT Knt_GIDTyp , Knt_GIDFirma , Knt_GIDNumer , Knt_GIDLp , 0 , KAR_Waluta , 0 , '' , Knt_KarNumer , '' , 0 FROM CDN.KntKarty INNER JOIN CDN.Rejestry ON KAR_GIDNumer = Knt_KarNumer WHERE Knt_KarNumer <> 0
SET NOCOUNT OFF;
